insert into public.industries (slug, name, summary, intro_md, icon_key, sort_order, published) values ('oil-gas', 'Oil & Gas', 'Chemical produksi & maintenance oil and gas dengan teknologi terbaru, didukung pakar R&D.', 'Kami terus mengikuti perkembangan teknologi chemical yang digunakan pada produksi oil and gas, sehingga chemicals yang kami tawarkan merupakan hasil teknologi terbaru. Kami memiliki pakar R&D berpengalaman untuk menjawab permasalahan di bidang oil & gas — mulai dari penanganan tumpahan, pemadaman api, pemisahan emulsi, hingga proteksi korosi.', 'oil-gas', 10, true) on conflict (slug) do update set name=excluded.name, summary=excluded.summary, intro_md=excluded.intro_md, icon_key=excluded.icon_key, sort_order=excluded.sort_order, published=true;
insert into public.industries (slug, name, summary, intro_md, icon_key, sort_order, published) values ('mining', 'Pertambangan', 'Mining maintenance chemicals: pengendalian debu, pendingin, pembersih, dan proteksi peralatan tambang.', 'Kami memiliki pengalaman dalam formulasi dan produksi specialty chemicals untuk keperluan perawatan di pertambangan. Formulasi yang kami tawarkan disesuaikan dengan kebutuhan customer dan benar-benar menjawab permasalahan di lapangan — dari pengendalian debu batu bara, pendinginan ban truk HD, hingga pembersihan sparepart.', 'mining', 20, true) on conflict (slug) do update set name=excluded.name, summary=excluded.summary, intro_md=excluded.intro_md, icon_key=excluded.icon_key, sort_order=excluded.sort_order, published=true;
insert into public.industries (slug, name, summary, intro_md, icon_key, sort_order, published) values ('manufacturing', 'Manufaktur & Industri', 'Chemical maintenance untuk industri & manufaktur: cleaning, coating, pelumas, dan anti-korosi.', 'Sebagai chemicals specialist, kami memformulasikan chemical untuk keperluan industri dan manufaktur. Produk yang kami tawarkan tidak terbatas pada list yang ada — kami juga menawarkan kerja sama riset dengan customer yang ingin mengembangkan produk dengan formula baru sesuai kebutuhan.', 'manufacturing', 30, true) on conflict (slug) do update set name=excluded.name, summary=excluded.summary, intro_md=excluded.intro_md, icon_key=excluded.icon_key, sort_order=excluded.sort_order, published=true;
insert into public.industries (slug, name, summary, intro_md, icon_key, sort_order, published) values ('water-treatment', 'Water Treatment', 'Chemical & technical service water treatment: koagulan, flokulan, biocide, scale & oxygen control.', 'Untuk melengkapi pelayanan di bidang chemical, kami menyediakan layanan water treatment. Selain chemical, kami juga menyediakan jasa technical service yang membantu melakukan injeksi chemical dan problem solving di lapangan.', 'water', 40, true) on conflict (slug) do update set name=excluded.name, summary=excluded.summary, intro_md=excluded.intro_md, icon_key=excluded.icon_key, sort_order=excluded.sort_order, published=true;
insert into public.industries (slug, name, summary, intro_md, icon_key, sort_order, published) values ('household', 'Household, Laundry & Toiletries', 'Produk kebutuhan household, laundry, dan general purpose cleaning dengan kualitas bagus & harga bersaing.', 'Kami memproduksi kebutuhan household, laundry, dan general purpose cleaning dengan kualitas yang bagus dan harga lebih bersaing. Kami juga menawarkan produk yang disesuaikan dengan permintaan pelanggan — dari pencuci piring, deterjen, pembersih lantai, hingga hand soap & sanitizer.', 'household', 50, true) on conflict (slug) do update set name=excluded.name, summary=excluded.summary, intro_md=excluded.intro_md, icon_key=excluded.icon_key, sort_order=excluded.sort_order, published=true;
insert into public.industries (slug, name, summary, intro_md, icon_key, sort_order, published) values ('automotive', 'Otomotif', 'Perawatan kendaraan: pembersih ruang bakar, karburator, shampo touchless, pelumas, dan water repellent.', 'Rangkaian produk perawatan kendaraan MIB membantu menjaga performa dan tampilan kendaraan — dari pembersih karbon ruang bakar, pembersih karburator, shampo touchless, hingga water repellent kaca.', 'autocare', 60, true) on conflict (slug) do update set name=excluded.name, summary=excluded.summary, intro_md=excluded.intro_md, icon_key=excluded.icon_key, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-spill-combat', 'MIB Spill Combat', (select id from public.industries where slug='oil-gas'), 'Tumpahan minyak di laut', 'MIB Spill Combat', 'Solusi penanganan tumpahan minyak di laut yang cepat menguraikan & menyebarkan minyak.', '**MIB SPILL COMBAT** adalah solusi untuk menangani tumpahan minyak di laut. Formula khususnya dengan cepat menguraikan dan menyebarkan minyak, mengurangi dampak lingkungan. Diuji untuk biodegradabilitas dan keamanan bagi lingkungan air, memenuhi standar ketat, serta dapat digunakan dengan berbagai metode aplikasi.', 10, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-fire-fight-foam', 'MIB Fire Fight Foam', (select id from public.industries where slug='oil-gas'), 'Kebakaran bahan bakar hidrokarbon', 'MIB Fire Fight Foam', 'Konsentrat busa pemadam api untuk bahan bakar minyak hidrokarbon.', '**MIB FIRE FIGHT FOAM** adalah cairan pembentuk busa yang diformulasikan sebagai konsentrat busa pemadam api. Digunakan dalam konsentrasi 3% dalam air. Efektif memadamkan bahan bakar minyak hidrokarbon seperti bensin, minyak tanah, dan solar, serta mengandung surfaktan yang menstabilkan busa dan melindungi dari *burnback*.', 20, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-demul', 'MIB Demul', (select id from public.industries where slug='oil-gas'), 'Emulsi minyak-air kompleks', 'MIB Demul (Demulsifier)', 'Memisahkan emulsi minyak-air kompleks dalam proses pengolahan minyak bumi.', '**MIB DEMUL** adalah produk untuk memisahkan emulsi minyak-air yang kompleks dalam proses pengolahan minyak bumi — mengoptimalkan stabilitas produksi, mengurangi gangguan operasional, dan memastikan operasi pengolahan yang lancar di berbagai tahapan.', 30, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-rust-shield', 'MIB Rust Shield', (select id from public.industries where slug='oil-gas'), 'Korosi permukaan logam', 'MIB Rust Shield', 'Perlindungan tahan lama terhadap korosi untuk berbagai permukaan logam.', '**MIB RUST SHIELD** memberikan perlindungan tahan lama terhadap korosi untuk berbagai permukaan logam. Formulanya menghambat pembentukan karat, kompatibel dengan besi, baja, aluminium, dan alloy. Aplikasi mudah melalui penyemprotan, pencelupan, atau penyikatan.', 40, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-dust-coal', 'MIB Dust Coal', (select id from public.industries where slug='mining'), 'Debu batu bara saat bongkar muat & crushing', 'MIB Dust Coal', 'Pengendali debu batu bara selama loading, unloading, crushing, atau transfer.', '**MIB DUST COAL** adalah solusi untuk mengendalikan debu batu bara selama proses bongkar muat, crushing, atau transfer. Dengan penggunaan teratur, membentuk lapisan proteksi efektif yang mengurangi pelepasan debu serta meningkatkan keamanan dan kebersihan di lokasi pengolahan batu bara.', 10, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-road-dust', 'MIB Road Dust', (select id from public.industries where slug='mining'), 'Debu jalan di lapangan tambang', 'MIB Road Dust', 'Penekan debu jalan yang sering muncul di lapangan pertambangan.', '**MIB ROAD DUST** adalah solusi pengendali debu di industri pertambangan, dirancang untuk menekan debu yang sering muncul di lapangan tambang. Penggunaan rutin membentuk lapisan protektif efektif yang mengurangi pelepasan debu dan meningkatkan keamanan serta kebersihan lokasi.', 20, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-tire-coolant', 'MIB Tire Coolant', (select id from public.industries where slug='mining'), 'Panas ban truk angkut material tambang (HD)', 'MIB Tire Coolant', 'Pendingin ban khusus truk angkut material tambang seperti truk HD.', '**MIB TIRE COOLANT** adalah cairan yang diformulasikan khusus untuk pendingin ban pada truk angkutan material tambang seperti truk HD. Selain mendinginkan dan menstabilkan suhu udara pada ban, juga memproteksi timbulnya karat pada rim/velg.', 30, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-radcool', 'MIB Radcool', (select id from public.industries where slug='mining'), 'Overheat & karat sistem pendingin mesin', 'MIB Radcool', 'Cairan pendingin radiator untuk mengoptimalkan sistem pendinginan mesin.', '**MIB RADCOOL** adalah cairan pendingin radiator yang diformulasikan untuk mengoptimalkan kinerja sistem pendinginan mesin dan berbagai aplikasi industri. Efisien menyerap panas, memastikan mesin beroperasi pada suhu optimal, mencegah overheat sekaligus mencegah karat.', 40, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-mounting-compound', 'MIB Mounting Compound', (select id from public.industries where slug='mining'), 'Pemasangan & pelepasan ban dari velg', 'MIB Mounting Compound', 'Pasta lubrikasi berbahan dasar air untuk memasang/melepas ban dari velg.', '**MIB MOUNTING COMPOUND** adalah material pasta *water based* untuk lubrikasi pemasangan dan pelepasan ban dari velg. Sisa aplikasi dapat dibilas air (meski tidak diperlukan), cocok untuk pemasangan ban manual maupun otomatis, serta aman untuk cat dan logam.', 50, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-fastclean', 'MIB Fastclean', (select id from public.industries where slug='mining'), 'Kotoran oli & gemuk yang mengering', 'MIB Fastclean', 'Pembersih berbasis air ramah lingkungan untuk oli & gemuk kering.', '**MIB FASTCLEAN** adalah pembersih berbasis air yang sangat ramah lingkungan, diformulasikan khusus untuk menghilangkan kotoran oli dan gemuk yang sudah mengering. Cocok untuk aplikasi general engineering, otomotif, dan industri pertambangan.', 60, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-waterless-hand-cleaner', 'MIB Waterless Hand Cleaner', (select id from public.industries where slug='manufacturing'), 'Pembersih tangan di area dengan air terbatas', 'MIB Waterless Hand Cleaner', 'Pembersih tangan berbentuk pasta aroma lemon tanpa perlu air.', '**MIB WATERLESS HAND CLEANER** adalah pembersih tangan berbentuk pasta beraroma lemon yang membersihkan tangan dari oli dan grease tanpa pembilasan air. Cocok untuk area tambang dengan ketersediaan air terbatas, aman, tidak korosif, dan lembut di tangan.', 10, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-bitguard', 'MIB Bitguard', (select id from public.industries where slug='manufacturing'), 'Kebutuhan waterproofing coating', 'MIB Bitguard', 'Emulsi bitumen berkualitas tinggi untuk aplikasi waterproofing coating.', '**MIB BITGUARD** adalah emulsi bitumen berkualitas tinggi untuk aplikasi *waterproofing coating*. Teknologi emulsinya menciptakan lapisan tahan air yang efektif melindungi permukaan dari penetrasi air — baik untuk atap, pondasi, atau struktur lain.', 20, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-multiclean-break', 'MIB Multiclean Break', (select id from public.industries where slug='manufacturing'), 'Kotoran, lemak, dan noda serbaguna', 'MIB Multiclean Break', 'Pembersih berbasis air serbaguna tanpa meninggalkan residu.', '**MIB MULTICLEAN BREAK** adalah pembersih berbasis air serbaguna untuk beragam aplikasi. Formulanya efektif menghilangkan kotoran, lemak, dan noda dari berbagai permukaan tanpa meninggalkan residu — konsisten dan andal untuk kebutuhan industri maupun sehari-hari.', 30, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-rust-combat', 'MIB Rust Combat', (select id from public.industries where slug='manufacturing'), 'Deposit karat yang sukar dihilangkan', 'MIB Rust Combat', 'Pembersih karat yang mengembalikan kilau permukaan logam.', '**MIB RUST COMBAT** adalah pembersih karat yang diformulasikan untuk mengembalikan kilau permukaan logam ke keadaan aslinya. Formulanya efektif melarutkan dan menghilangkan deposit karat yang sukar dihilangkan.', 40, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-natlube', 'MIB Natlube', (select id from public.industries where slug='manufacturing'), 'Gesekan & keausan mesin', 'MIB Natlube', 'Pelumas minyak alami premium yang mengurangi gesekan & keausan.', '**MIB NATLUBE** adalah pelumas minyak alami premium yang memberikan pelumasan dan perlindungan unggul. Diformulasikan dari minyak alami terpilih, efektif mengurangi gesekan dan keausan pada mesin & peralatan — pilihan ramah lingkungan untuk operasi yang lancar dan efisien.', 50, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-coanor', 'MIB Coanor', (select id from public.industries where slug='water-treatment'), 'Air keruh oleh partikel tersuspensi', 'MIB Coanor (Coagulant)', 'Coagulant penjernih kinerja tinggi untuk berbagai aplikasi industri.', '**MIB COANOR** adalah coagulant penjernih kinerja tinggi yang menjernihkan air secara efektif. Formulanya mempromosikan agregasi cepat partikel tersuspensi, memungkinkan penjernihan melalui pengendapan atau filtrasi.', 10, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-flocar', 'MIB Flocar', (select id from public.industries where slug='water-treatment'), 'Pemisahan & pengendapan partikel tersuspensi', 'MIB Flocar (Flocculant)', 'Flokulan penjernih untuk meningkatkan pemisahan & pengendapan partikel.', '**MIB FLOCAR** adalah floculant penjernih kinerja tinggi yang meningkatkan pemisahan dan pengendapan partikel tersuspensi dalam proses penjernihan air. Formulanya mempromosikan agregasi cepat partikel halus, memfasilitasi pemisahan pengotor dari air.', 20, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-binox', 'MIB Binox', (select id from public.industries where slug='water-treatment'), 'Pertumbuhan mikroba dalam sistem air', 'MIB Binox (Biocide)', 'Biocide kinerja tinggi untuk mengendalikan pertumbuhan mikroba.', '**MIB BINOX** adalah biocide berkinerja tinggi untuk mengendalikan pertumbuhan mikroba dalam sistem pengolahan air. Formulanya membunuh berbagai bakteri, alga, dan jamur — melindungi dari kontaminasi mikrobiologis dan memastikan kualitas air optimal.', 30, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-scalin', 'MIB Scalin', (select id from public.industries where slug='water-treatment'), 'Kerak & deposit mineral pada sistem air', 'MIB Scalin (Scale Inhibitor)', 'Scale inhibitor untuk mencegah pembentukan kerak/deposit mineral.', '**MIB SCALIN** adalah scale inhibitor kinerja tinggi untuk mengontrol dan mencegah pembentukan kerak atau deposit mineral dalam sistem pengolahan air. Menyasar proses kristalisasi mineral pembentuk kerak, memperpanjang umur operasional peralatan.', 40, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-osca', 'MIB Osca', (select id from public.industries where slug='water-treatment'), 'Oksigen terlarut penyebab korosi', 'MIB Osca (Oxygen Scavenger)', 'Oxygen scavenger untuk menghilangkan oksigen terlarut & mencegah korosi.', '**MIB OSCA** adalah oxygen scavenger efektif untuk menghilangkan oksigen terlarut dalam air. Mengikat molekul oksigen, mencegah korosi, dan mempertahankan integritas permukaan logam — komponen penting dalam proses pengolahan air.', 50, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('kiklin-lemon-dishwash', 'Kiklin Lemon Dishwash', (select id from public.industries where slug='household'), 'Lemak & kotoran pada peralatan makan', 'Kiklin Lemon Dishwash', 'Cairan pencuci piring beraroma lemon yang menghilangkan lemak.', '**KIKLIN-LEMON DISHWASH** adalah cairan pencuci piring berkualitas tinggi dengan aroma lemon menyegarkan. Formulanya mudah menghilangkan lemak dari kotoran, meninggalkan piring bersih bersinar dan beraroma lemon.', 10, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('kiklin-wash', 'Kiklin Wash', (select id from public.industries where slug='household'), 'Noda & bau pada pakaian', 'Kiklin Wash', 'Deterjen pencuci pakaian kinerja tinggi.', '**KIKLIN WASH** adalah deterjen pencuci pakaian kinerja tinggi yang berpenetrasi ke serat kain, menghilangkan noda dan bau yang sulit dihilangkan — membuat cucian bersih, cerah, dan beraroma segar.', 20, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('kiklin-floor', 'Kiklin Floor', (select id from public.industries where slug='household'), 'Lantai kotor & butuh efek anti-bakteri', 'Kiklin Floor', 'Pembersih lantai keramik dengan efek anti-bakteri, aroma pinus/sereh.', '**KIKLIN FLOOR** diformulasikan khusus untuk membersihkan lantai keramik secara menyeluruh sekaligus memberi efek anti-bakteri. Tersedia dua aroma — pinus segar atau sereh — meninggalkan lantai bersih dengan aroma menyegarkan tahan lama.', 30, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('dominatus-multipurpose-cleaner', 'Dominatus Multipurpose Cleaner', (select id from public.industries where slug='household'), 'Pembersihan berbagai permukaan tanpa air', 'Dominatus Multipurpose Cleaner', 'Pembersih serbaguna untuk sepatu, tas, sofa, & interior mobil tanpa air.', '**DOMINATUS MULTIPURPOSE CLEANER** adalah solusi pembersih serbaguna yang mudah digunakan untuk membersihkan berbagai permukaan kotor secara efisien tanpa perlu air — membuat sepatu, tas, sofa, dan interior mobil kembali bersih seperti baru.', 40, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('kiklin-handsoap', 'Kiklin Handsoap', (select id from public.industries where slug='household'), 'Kebersihan tangan sehari-hari', 'Kiklin Handsoap', 'Pembersih tangan berkualitas yang lembut namun efektif.', '**KIKLIN HANDSOAP** adalah pembersih tangan berkualitas tinggi yang efektif menghilangkan kotoran, kuman, dan zat asing. Formulanya lembut namun efektif, membuat kulit bersih, segar, dan terhidrasi.', 50, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('kiklin-handsan', 'Kiklin Handsan', (select id from public.industries where slug='household'), 'Disinfeksi tangan saat air & sabun tak tersedia', 'Kiklin Handsan', 'Hand sanitizer dengan kandungan alkohol seimbang.', '**KIKLIN HANDSAN** adalah disinfektan tangan yang efektif membunuh kuman dan bakteri pada permukaan kulit. Kandungan alkoholnya seimbang — disinfeksi unggul namun tetap lembut, penting untuk menjaga kebersihan tangan saat air dan sabun tidak tersedia.', 60, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-carb-cleaner', 'MIB Carb Cleaner', (select id from public.industries where slug='automotive'), 'Varnish & endapan karbon pada karburator', 'MIB Carb Cleaner', 'Pembersih ampuh varnish & endapan karbon tanpa merusak komponen karburator.', '**MIB CARB CLEANER** adalah cairan pembersih yang ampuh menghilangkan dan membersihkan varnish dan endapan karbon tanpa merusak komponen karburator lainnya.', 10, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-carb-conditioner', 'MIB Carb Conditioner', (select id from public.industries where slug='automotive'), 'Kerak oli & karbon di ruang bakar', 'MIB Carb Conditioner', 'Waterbase; membersihkan kotoran karbon & kerak oli ruang bakar, kembalikan performa.', '**MIB CARB CONDITIONER** (waterbase) membersihkan kotoran karbon dan kerak oli di ruang bakar mesin. Mengembalikan performa mesin menjadi lebih responsif, menghilangkan gejala ngelitik (knocking), serta meningkatkan efisiensi bahan bakar.', 20, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-carwash-tl', 'MIB Carwash TL (Touchless)', (select id from public.industries where slug='automotive'), 'Pencucian kendaraan tanpa kontak', 'MIB Carwash TL', 'Shampo mobil/motor touchless dengan busa lembut & hasil mengkilap.', '**MIB CARWASH TL (Touch Less)** adalah shampo mobil/motor yang memberikan kelembutan dan kilau maksimal. Busa lembutnya membersihkan sempurna tanpa perlu menyentuh permukaan yang dibersihkan, dengan hasil licin dan mengkilap.', 30, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-lub', 'MIB Lub', (select id from public.industries where slug='automotive'), 'Bagian berkarat & butuh pelumasan', 'MIB Lub', 'Melunturkan bagian berkarat, membersihkan, melindungi, melumasi & anti lengket.', '**MIB LUB** melunturkan bagian yang berkarat, membersihkan, serta melindungi, melumasi, dan bersifat anti lengket — solusi perawatan komponen kendaraan serbaguna.', 40, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
insert into public.solutions (slug, title, industry_id, problem, solution_label, summary, body_md, sort_order, published) values ('mib-windshield-water-repellent', 'MIB Windshield Water Repellent', (select id from public.industries where slug='automotive'), 'Noda air/jamur pada permukaan kaca kendaraan', 'MIB Windshield Water Repellent', 'Menghilangkan noda air/jamur membandel pada permukaan kendaraan.', '**MIB WINDSHIELD WATER REPELLENT** dirancang untuk menghilangkan noda air/jamur membandel pada permukaan kendaraan, mengembalikan tampilan sempurna. Formula canggihnya memastikan proses penghilangan noda cepat dan efektif.', 50, true) on conflict (slug) do update set title=excluded.title, industry_id=excluded.industry_id, problem=excluded.problem, solution_label=excluded.solution_label, summary=excluded.summary, body_md=excluded.body_md, sort_order=excluded.sort_order, published=true;
